  IonInput,
  IonTextarea,
  IonToggle,
  IonLoading,
  IonToast,
  IonAlert,
  IonNote,
  IonSpinner,
  IonSearchbar,
  IonInfiniteScroll,
  IonInfiniteScrollContent,
  SearchbarInputEventDetail
} from '@ionic/react';
import { addOutline, createOutline, trashOutline, closeOutline, saveOutline, peopleOutline, chevronForward } from 'ionicons/icons';
import { useUser } from '../contexts/UserContext';
import Header from '../components/Header';
import AlertPopover from '../components/PopOver/AlertPopover';
import MailPopover from '../components/PopOver/MailPopover';
import { createSupplier, deleteSupplier, getAllSuppliers, updateSupplier, Supplier } from '../api/supplierApi';
import './SupplierPage.css';
import { SearchbarInputEventDetail } from '@ionic/core';

const toHermosillo = (utc: string | undefined | null): string => {
  if (!utc) return '';
  const d = new Date(utc.includes('Z') ? utc : utc + 'Z');
  // Subtract 7 hours for UTC-7 (Hermosillo time zone)
  return new Date(d.getTime() - 7 * 60 * 60 * 1000).toLocaleString('es-MX', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: true,
  });
};

interface FormState {
  supplierName: string;
  contactName: string;
  phone: string;
  email: string;
  address: string;
  active: boolean;
}

const initialState: FormState = {
  supplierName: '',
  contactName: '',
  phone: '',
  email: '',
  address: '',
  active: true,
};

const SupplierPage: React.FC = () => {
  const { companyId, roleCode } = useUser();
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [showAddEditModal, setShowAddEditModal] = useState(false);
  const [editingSupplier, setEditingSupplier] = useState<Supplier | null>(null);
  const [formState, setFormState] = useState<FormState>(initialState);
  const [formErrors, setFormErrors] = useState<Partial<Record<keyof FormState, string>>>({});
  const [showDeleteAlert, setShowDeleteAlert] = useState(false);
  const [supplierToDelete, setSupplierToDelete] = useState<Supplier | null>(null);
  const [searchText, setSearchText] = useState('');

  const [popoverState, setPopoverState] = useState<{
    showAlertPopover: boolean;
    showMailPopover: boolean;
    event?: Event;
  }>({ showAlertPopover: false, showMailPopover: false });

  const presentAlertPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showAlertPopover: true, event: e.nativeEvent });
  const dismissAlertPopover = () =>
    setPopoverState({ ...popoverState, showAlertPopover: false });
  const presentMailPopover = (e: React.MouseEvent) =>
    setPopoverState({ ...popoverState, showMailPopover: true, event: e.nativeEvent });
  const dismissMailPopover = () =>
    setPopoverState({ ...popoverState, showMailPopover: false });

  const canEdit = useMemo(() => ['admin', 'manager'].includes(roleCode), [roleCode]);

  const validateForm = (): boolean => {
    const errors: Partial<Record<keyof FormState, string>> = {};
    if (!formState.supplierName.trim()) {
      errors.supplierName = 'El nombre del proveedor es obligatorio.';
    }
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  const loadSuppliers = async () => {
    if (!companyId) return;
    setLoading(true);
    setError('');
    try {
      const data = await getAllSuppliers(companyId);
      setSuppliers(data);
    } catch (err) {
      setError((err as Error).message ?? 'Error al cargar proveedores.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadSuppliers();
  }, [companyId]);

  // Refetch on view re-enter for Ionic lifecycle
  // useIonViewWillEnter(() => {
  //   loadSuppliers();
  // }, [companyId]); // Removed as per discussion, useEffect handles initial load and subsequent logic should re-trigger when necessary

  const handleAddSupplier = () => {
    setEditingSupplier(null);
    setFormState(initialState);
    setFormErrors({});
    setShowAddEditModal(true);
  };

  const handleEditSupplier = (supplier: Supplier) => {
    setEditingSupplier(supplier);
    setFormState({
      supplierName: supplier.supplierName,
      contactName: supplier.contactName ?? '',
      phone: supplier.phone ?? '',
      email: supplier.email ?? '',
      address: supplier.address ?? '',
      active: supplier.active === '1',
    });
    setFormErrors({});
    setShowAddEditModal(true);
  };

  const handleSaveSupplier = async () => {
    if (!companyId) {
      setError('Company ID no disponible.');
      return;
    }
    if (!validateForm()) return;

    setSaving(true);
    setError('');
    try {
      const payload = {
        ...formState,
        companyId,
        active: formState.active ? '1' : '0',
      };

      if (editingSupplier) {
        await updateSupplier(editingSupplier.supplierId, payload);
      } else {
        await createSupplier(payload);
      }
      await loadSuppliers();
      setShowAddEditModal(false);
      setError(''); // Clear any previous errors
    } catch (err) {
      setError((err as Error).message ?? 'Error al guardar proveedor.');
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteClick = (supplier: Supplier) => {
    setSupplierToDelete(supplier);
    setShowDeleteAlert(true);
  };

  const confirmDeleteSupplier = async () => {
    if (!supplierToDelete || !companyId) return;
    setLoading(true);
    setError('');
    try {
      await deleteSupplier(supplierToDelete.supplierId, companyId);
      await loadSuppliers();
      setError(''); // Clear any previous errors
    } catch (err) {
      setError((err as Error).message ?? 'Error al eliminar proveedor.');
    } finally {
      setLoading(false);
      setSupplierToDelete(null);
    }
  };

  const filteredSuppliers = useMemo(() => {
    return suppliers.filter(supplier =>
      supplier.supplierName.toLowerCase().includes(searchText.toLowerCase()) ||
      (supplier.contactName?.toLowerCase().includes(searchText.toLowerCase())) ||
      (supplier.email?.toLowerCase().includes(searchText.toLowerCase()))
    );
  }, [suppliers, searchText]);

  // Infinite scroll, assuming all data is loaded initially or handled by backend pagination if implemented.
  const loadMoreItems = (ev: CustomEvent<void>) => {
    // In this basic CRUD example, we assume `getAllSuppliers` loads all data.
    // If backend pagination existed, we would fetch the next page here.
    (ev.target as HTMLIonInfiniteScrollElement).complete();
  };

  return (
    <IonPage>
      <Header
        presentAlertPopover={presentAlertPopover}
        presentMailPopover={presentMailPopover}
        screenTitle="Proveedores — POS GMO"
      />
      <AlertPopover
        isOpen={popoverState.showAlertPopover}
        event={popoverState.event}
        onDidDismiss={dismissAlertPopover}
      />
      <MailPopover
        isOpen={popoverState.showMailPopover}
        event={popoverState.event}
        onDidDismiss={dismissMailPopover}
      />

      <IonLoading isOpen={loading} message="Cargando proveedores..." spinner="crescent" />
      <IonToast
        isOpen={!!error}
        message={error}
        duration={3000}
        onDidDismiss={() => setError('')}
        color="danger"
      />

      <IonContent fullscreen className="supplier-page">
        <IonSearchbar
          placeholder="Buscar proveedores..."
          value={searchText}
          onIonInput={(e: CustomEvent<SearchbarInputEventDetail>) => setSearchText(e.detail.value!)}
          className="supplier-searchbar"
        />

        <IonList className="supplier-list ion-padding-top">
          {filteredSuppliers.length === 0 && !loading && searchText === '' && (
            <IonItem>
              <IonLabel className="ion-text-center">No hay proveedores disponibles.</IonLabel>
            </IonItem>
          )}
          {filteredSuppliers.length === 0 && !loading && searchText !== '' && (
            <IonItem>
              <IonLabel className="ion-text-center">No se encontraron proveedores para "{searchText}".</IonLabel>
            </IonItem>
          )}

          {filteredSuppliers.map((supplier) => (
            <IonItem key={supplier.supplierId} className="supplier-item ion-margin-bottom ion-item-divider-none">
              <IonLabel className="ion-text-wrap">
                <div className="supplier-name-row">
                  <h2 className="supplier-name">{supplier.supplierName}</h2>
                  <IonNote className={`supplier-status supplier-status-${supplier.active === '1' ? 'active' : 'inactive'}`}>
                    {supplier.active === '1' ? 'Activo' : 'Inactivo'}
                  </IonNote>
                </div>
                <p className="supplier-contact">Contacto: {supplier.contactName || 'N/A'}</p>
                <p className="supplier-details">Tel: {supplier.phone || 'N/A'}</p>
                <p className="supplier-details">Email: {supplier.email || 'N/A'}</p>
                <p className="supplier-details">Dirección: {supplier.address || 'N/A'}</p>
                <IonNote className="supplier-dates">
                  Creado: {toHermosillo(supplier.created_At)}
                  {supplier.updated_at && ` | Actualizado: ${toHermosillo(supplier.updated_at)}`}
                </IonNote>
              </IonLabel>
              {canEdit && (
                <div className="supplier-actions">
                  <IonButton fill="clear" color="medium" onClick={() => handleEditSupplier(supplier)}>
                    <IonIcon icon={createOutline} />
                  </IonButton>
                  <IonButton fill="clear" color="danger" onClick={() => handleDeleteClick(supplier)}>
                    <IonIcon icon={trashOutline} />
                  </IonButton>
                </div>
              )}
            </IonItem>
          ))}
        </IonList>

        <IonInfiniteScroll onIonInfinite={loadMoreItems}>
          <IonInfiniteScrollContent loadingText="Cargando más proveedores..."></IonInfiniteScrollContent>
        </IonInfiniteScroll>

        {canEdit && (
          <IonFab vertical="bottom" horizontal="end" slot="fixed">
            <IonFabButton onClick={handleAddSupplier}>
              <IonIcon icon={addOutline} />
            </IonFabButton>
          </IonFab>
        )}

        <IonModal isOpen={showAddEditModal} onDidDismiss={() => setShowAddEditModal(false)} className="supplier-modal">
          <IonHeader>
            <IonToolbar>
              <IonTitle>{editingSupplier ? 'Editar Proveedor' : 'Agregar Proveedor'}</IonTitle>
              <IonButtons slot="end">
                <IonButton onClick={() => setShowAddEditModal(false)}>
                  <IonIcon icon={closeOutline} />
                </IonButton>
              </IonButtons>
            </IonToolbar>
          </IonHeader>
          <IonContent className="ion-padding">
            <form onSubmit={e => { e.preventDefault(); handleSaveSupplier(); }}>
              <div className="supplier-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre del Proveedor *"
                  labelPlacement="floating"
                  value={formState.supplierName}
                  onIonInput={(e: CustomEvent) => setFormState(p => ({ ...p, supplierName: e.detail.value! }))}
                  className={formErrors.supplierName ? 'ion-invalid ion-touched' : ''}
                  errorText={formErrors.supplierName}
                />
              </div>
              <div className="supplier-field-group">
                <IonInput
                  fill="outline"
                  label="Nombre de Contacto"
                  labelPlacement="floating"
                  value={formState.contactName}
                  onIonInput={(e: CustomEvent) => setFormState(p => ({ ...p, contactName: e.detail.value! }))}
                />
              </div>
              <div className="supplier-field-group">
                <IonInput
                  fill="outline"
                  label="Teléfono"
                  labelPlacement="floating"
                  type="tel"
                  value={formState.phone}
                  onIonInput={(e: CustomEvent) => setFormState(p => ({ ...p, phone: e.detail.value! }))}
                />
              </div>
              <div className="supplier-field-group">
                <IonInput
                  fill="outline"
                  label="Email"
                  labelPlacement="floating"
                  type="email"
                  value={formState.email}
                  onIonInput={(e: CustomEvent) => setFormState(p => ({ ...p, email: e.detail.value! }))}
                />
              </div>
              <div className="supplier-field-group">
                <IonTextarea
                  fill="outline"
                  label="Dirección"
                  labelPlacement="floating"
                  rows={3}
                  value={formState.address}
                  onIonInput={(e: CustomEvent) => setFormState(p => ({ ...p, address: e.detail.value! }))}
                />
              </div>
              <IonItem className="supplier-toggle-item">
                <IonLabel>Activo</IonLabel>
